insert into public.documents (content, metadata, embedding) values ('# Universitaet Musterstadt - Fiktive FAQ fuer den Service-Bot

Dokument: uni_faq.txt
Stand: Sommersemester 2026

## Rueckmeldung
Studierende muessen sich fuer das Sommersemester bis spaetestens 15. Februar
zurueckmelden. Fuer das Wintersemester endet die Rueckmeldefrist am 15. August.
Die Rueckmeldung ist nur vollstaendig, wenn der Semesterbeitrag fristgerecht auf
dem Konto der Universitaet eingegangen ist.', '{"source": "uni_faq.txt", "chunk": 0}'::jsonb, '[-0.0189081700,0.0158045810,0.0064507610,-0.0664344950,0.0000232437,0.0082184800,-0.0102039390,-0.0089538600,0.0018119157,0.0091535640,-0.0147431280,-0.0183663070,-0.0142898240,0.0118494040,0.1407901500,0.0284568440,-0.0097751925,0.0025689206,-0.0179363600,-0.0148322810,0.0129118840,-0.0004263483,-0.0111047040,0.0117942730,-0.0060261856,-0.0065346210,0.0140387720,0.0120704150,0.0376981900,-0.0125936745,0.0003376636,0.0336325060,-0.0033454620,0.0290721260,0.0056154323,0.0155396490,0.0329304640,0.0111836055,0.0051365700,0.0177167500,0.0135897910,0.0054260910,0.0045669023,-0.0261624940,-0.0004567548,0.0165262580,-0.0281064580,-0.0380662530,0.0022079325,0.0309018660,-0.0024856806,-0.0044587740,-0.0215363200,-0.2060560400,0.0113243550,-0.0250954800,-0.0181242770,0.0117653540,-0.0048630050,-0.0323114660,-0.0253296810,0.0239481800,-0.0185974580,-0.0353879700,0.0047967914,0.0066803065,-0.0010607246,0.0240694800,-0.0051204762,-0.0017312241,-0.0055828276,-0.0149923020,0.0065593026,-0.0155533820,-0.0048869234,-0.0429781080,0.0096793035,-0.0011060757,0.0056829330,0.0191305600,-0.0072748750,-0.0203787780,-0.0047075270,-0.0283888500,0.0096488730,-0.0113207930,-0.0041807940,-0.0052607195,-0.0117517750,-0.0113758920,0.0102349250,0.0010369055,0.0020567642,-0.0072300680,-0.0122774900,-0.0103143420,0.0019748549,0.0009071198,0.0008853913,-0.0181446930,-0.0248967040,0.0043419670,-0.0239538420,0.0105804880,0.0084937615,-0.0097381210,0.0130212010,0.0104772720,0.0083949160,0.0139201330,0.0138460650,-0.0053902890,0.0015159678,0.0053331573,-0.0053140433,-0.1964664300,0.0131046460,-0.0206339140,0.0101916600,0.0006407940,-0.0256975540,0.0123929270,-0.0053211856,0.0061313948,0.0279473160,0.0002203753,0.0229140150,-0.0271171180,-0.0033822200,-0.0172495400,-0.0171958130,-0.0113297190,-0.0119665570,0.0101353260,0.0190182370,0.0264239260,-0.0406123920,-0.0043922400,0.0015637373,-0.0023073086,0.0001202728,