insert into public.documents (content, metadata, embedding) values ('## Studierendenausweis
Der Studierendenausweis kann nach erfolgreicher Rueckmeldung an den
Validierungsstationen auf dem Campus aktualisiert werden. Bei Verlust wird ein
Ersatzausweis gegen eine Gebuehr von 15 Euro im Studierendensekretariat
